from gen import *
r=Robot();obs=observe(r);cam='robot0_eye_in_hand';T=np.array(obs.meta['cameras'][cam]['cam2world_gl']);K=np.array(obs.meta['cameras'][cam]['intrinsic_cv']);ee=state(r)[1]
def proj(X):
 p=np.linalg.inv(T)@np.r_[X,1];cv=np.array([p[0],-p[1],-p[2]]);return np.round((K@cv)[:2]/cv[2],1),round(cv[2],3)
im=obs.last[cam].astype(int);D=np.asarray(obs.depth[cam])[0];
for name,roi,maskfun in [('bread',(slice(45,195),slice(90,230)),lambda a:(a[:,:,0]>110)&(a[:,:,1]<110)&(a[:,:,2]<130)),('cheese',(slice(120,210),slice(80,180)),lambda a:(a[:,:,0]>170)&(a[:,:,1]>100)&(a[:,:,2]<100))]:
 sub=im[roi]; d=D[roi]; m=maskfun(sub)&(d>0);yy,xx=np.where(m);x0=xx+roi[1].start;y0=yy+roi[0].start;pts=[]
 for u,v in zip(x0,y0):
  p=np.linalg.inv(K)@np.array([u,v,1.])*D[v,u]; pts.append((T@np.array([p[0],-p[1],-p[2],1]))[:3])
 print(name,'pixels',len(pts),'uv',np.round([np.median(x0),np.median(y0)],1),'world',np.round(np.median(pts,axis=0),4) if pts else None)
print('eef',ee,'proj',proj(ee));print('budget',obs.meta.get('time_left_s'))
